 const sortedFiltered=useMemo(()=>{
  const collator=new Intl.Collator("ar",{numeric:true,sensitivity:"base"});
  const valueFor=(item:Subscriber):string|number=>{
   switch(sortField){
    case "id":return item.id;
    case "phone":return item.phone||"";
    case "category":return item.categories||"";
    case "status":return item.status==="active"?0:1;
    case "identity_verified":return Number(item.identity_verified)===1?0:1;
    default:return `${item.first_name} ${item.last_name}`.trim();
   }
  };
  return [...filtered].sort((a,b)=>{
   const left=valueFor(a),right=valueFor(b);
   const order=typeof left==="number"&&typeof right==="number"?left-right:collator.compare(String(left),String(right));
   return sortDirection==="asc"?order:-order;
  });
 },[filtered,sortField,sortDirection]);
