 const toSubscriberPppoeLine=(customerId:number,line:SubscriberPppoeLine,customerName?:string):SubscriberLine=>({...line,customer_id:customerId,customer_name:customerName||null,kind:"pppoe",upload_bytes:0,download_bytes:0,last_seen:null,framed_ip:null,calling_station:null,nas_ip:null});
 const dispatchPppoeDetailAction=(sourceLine:SubscriberLine,action:string)=>{const line={...sourceLine,customer_id:Number(sourceLine.customer_id||detail?.id)||undefined};if(action==="monitor"){setPppoeSpeedLine(line);void fetch(`${endpoint}/subscribers/${line.customer_id}`,{credentials:"include",cache:"no-store"}).then(async response=>{const data=await response.json();if(!response.ok)throw new Error(data.message||"تعذر تحميل بيانات مراقبة الخط.");const latest=(Array.isArray(data.accounts)?data.accounts:[]).find((account:any)=>account.kind==="pppoe"&&Number(account.id)===line.id) as SubscriberLine|undefined;if(latest)setPppoeSpeedLine({...latest,customer_id:line.customer_id});}).catch(error=>{setPppoeSpeedLine(null);setPppoeNoticeError(error instanceof Error?error.message:"تعذر تحميل بيانات مراقبة الخط.");});}else if(action==="speed-boost")openPppoeSpeedBoost(line);else if(action==="history")void openPppoeUsageHistory(line);else if(action==="extend"||action==="expiry")openPppoeExpiryEditor(line);else if(action==="renew"||action==="disconnect")void runPppoeLineAction(line,action);else if(action==="end")setPppoeEndLine(line);else if(action==="archive")setPppoeArchiveLine(line);else if(action==="activate"||action==="enable"||action==="disable")void updatePppoeLine(line,action);};
