   <div aria-hidden="true" className="absolute inset-x-[16.66%] top-[22px] h-[2px] bg-[#dbe5f0] dark:bg-white/[.12]"><span className={`block h-full origin-right bg-gradient-to-l from-[#0758e9] to-[#42a5ff] transition-[width] duration-500 ease-out ${pppoeStep===1?"w-0":pppoeStep===2?"w-1/2":"w-full"}`}/></div>
